import sys, os, json
sys.path.insert(0, '/data/scripts')
import requests as req
import flowsint_client as fc

FLOWSINT_URL = os.environ.get('FLOWSINT_API_URL', 'http://flowsint-api:5001').rstrip('/')
KEY          = os.environ.get('FLOWSINT_API_KEY', '')
SK = os.environ.get('FLOWSINT_SKETCH_ID', '')
_sb = _items[0].get('json', {}) if _items else {}
_sb = _sb.get('body', _sb) if isinstance(_sb.get('body'), dict) else _sb
SK = _sb.get('sketch_id') or SK
HJ           = {'Authorization': f'Bearer {KEY}', 'Content-Type': 'application/json'}

item = _items[0].get('json', {}) if _items else {}
body = item.get('body', item) if isinstance(item.get('body'), dict) else item

ind_id   = (body.get('individual_id') or '').strip()
action   = (body.get('action') or '').strip().lower()
photo_url = (body.get('photo_url') or '').strip()

if not ind_id:
    return [{'json': {'ok': False, 'error': 'individual_id is required'}}]
if action not in ('verify', 'false_positive'):
    return [{'json': {'ok': False, 'error': "action must be 'verify' or 'false_positive'"}}]
if not photo_url:
    return [{'json': {'ok': False, 'error': 'photo_url is required'}}]

# Fetch current node properties to merge false positives list.
# Looked up by elementId directly rather than by downloading the whole sketch and
# scanning it: GET /graph is unpaginated and runs 110-235s on an AD-sized sketch,
# so this single-node read used to risk the 120s timeout to find one node.
try:
    node = fc.get_node_by_id(ind_id, sketch_id=SK)
    if not node:
        return [{'json': {'ok': False, 'error': f'Individual {ind_id} not found'}}]
    props = node.get('nodeProperties') or {}
except Exception as e:
    return [{'json': {'ok': False, 'error': f'Graph fetch failed: {e}'}}]

upd = {}
if action == 'verify':
    upd['nodeProperties.photo_verified_url'] = photo_url
    # Remove from false positives if it was previously flagged
    raw_fp = props.get('photo_false_positives') or '[]'
    try:
        fp_list = json.loads(raw_fp) if isinstance(raw_fp, str) else (raw_fp if isinstance(raw_fp, list) else [])
    except Exception:
        fp_list = []
    if photo_url in fp_list:
        fp_list.remove(photo_url)
        upd['nodeProperties.photo_false_positives'] = json.dumps(fp_list)
else:  # false_positive
    raw_fp = props.get('photo_false_positives') or '[]'
    try:
        fp_list = json.loads(raw_fp) if isinstance(raw_fp, str) else (raw_fp if isinstance(raw_fp, list) else [])
    except Exception:
        fp_list = []
    if photo_url not in fp_list:
        fp_list.append(photo_url)
    upd['nodeProperties.photo_false_positives'] = json.dumps(fp_list)
    # If the verified photo is the one being flagged, clear it
    if props.get('photo_verified_url') == photo_url:
        upd['nodeProperties.photo_verified_url'] = ''

try:
    r2 = req.put(f'{FLOWSINT_URL}/api/sketches/{SK}/nodes/edit', headers=HJ,
                 json={'nodeId': ind_id, 'updates': upd}, timeout=20)
    r2.raise_for_status()
    return [{'json': {'ok': True, 'individual_id': ind_id, 'action': action, 'photo_url': photo_url}}]
except Exception as e:
    return [{'json': {'ok': False, 'error': f'Node update failed: {e}'}}]
